<div class="admin-heading-row"><div><h1 class="admin-page-title">Order Status</h1><p class="admin-page-subtitle">Review customer, delivery, payment, and product information.</p></div><a class="btn btn-outline-brand" href="/admin/orders"><i class="fa-solid fa-arrow-left me-2"></i>All Orders</a></div>
