<div class="admin-detail-grid">
    <div>
        <section class="admin-panel"><h2><i class="fa-solid fa-user me-2"></i>Customer & Delivery</h2><dl class="row mt-4 mb-0"><dt class="col-sm-4">Customer</dt><dd class="col-sm-8"><?= esc($user->display_name ?? $user->username ?? '') ?> · <?= esc($user->email ?? '') ?></dd><dt class="col-sm-4">Phone</dt><dd class="col-sm-8"><?= esc($order['phone']) ?></dd><dt class="col-sm-4">Delivery address</dt><dd class="col-sm-8"><?= esc(implode(', ',[$order['address'],$order['city'],$order['region'],$order['postal_code']])) ?></dd><dt class="col-sm-4">Delivery method</dt><dd class="col-sm-8"><?= esc($order['delivery_method']) ?></dd><dt class="col-sm-4">Payment method</dt><dd class="col-sm-8">GCash</dd><dt class="col-sm-4">GCash sender</dt><dd class="col-sm-8"><?= esc(($order['gcash_name'] ?? '—') . (!empty($order['gcash_number']) ? ' · ' . $order['gcash_number'] : '')) ?></dd><dt class="col-sm-4">Payment reference</dt><dd class="col-sm-8"><?= esc($order['payment_reference']) ?></dd><dt class="col-sm-4">Proof of payment</dt><dd class="col-sm-8"><a href="/admin/orders/<?= esc($orderId) ?>/proof"><i class="fa-solid fa-paperclip me-2"></i>Download protected file</a></dd><?php if(!empty($order['comments'])): ?><dt class="col-sm-4">Comments</dt><dd class="col-sm-8"><?= nl2br(esc($order['comments'])) ?></dd><?php endif; ?></dl></section>
        <section class="admin-panel"><h2><i class="fa-solid fa-bag-shopping me-2"></i>Tendered Products</h2><div class="table-responsive mt-3"><table class="table align-middle"><thead><tr><th>Product</th><th>Variant</th><th>Quantity</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><strong><?= esc($item['product_name']) ?></strong></td><td><?= esc($item['variant'] ?: '—') ?></td><td>x<?= esc($item['quantity']) ?></td><td><span class="admin-price">₱<?= number_format((float)$item['line_total'],2) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section>
