    <aside>
        <form method="post" action="/admin/orders/<?= esc($orderId) ?>/status" class="admin-panel"><h2><i class="fa-solid fa-pen me-2"></i>Update Status</h2><label class="form-label mt-3" for="order-status">Order status</label><select class="form-select" id="order-status" name="status"><?php foreach(['received','approved','shipped','delivered','cancelled'] as $status): ?><option value="<?= $status ?>" <?= $order['status']===$status?'selected':'' ?>><?= ucfirst($status) ?></option><?php endforeach; ?></select><button class="btn btn-brand w-100 mt-3"><i class="fa-solid fa-floppy-disk me-2"></i>Save Changes</button></form>
        <section class="admin-panel"><h2><i class="fa-solid fa-link me-2"></i>Jotform Sync</h2><p class="mt-3"><span class="admin-status <?= $order['jotform_status']==='synced'?'admin-status-success':($order['jotform_status']==='failed'?'admin-status-danger':'admin-status-neutral') ?>"><?= esc(str_replace('_',' ',$order['jotform_status'])) ?></span></p><?php if($order['jotform_submission_id']): ?><a href="https://www.jotform.com/submission/<?= rawurlencode($order['jotform_submission_id']) ?>" target="_blank" rel="noopener"><i class="fa-solid fa-arrow-up-right-from-square me-2"></i>Open submission</a><?php endif; ?><?php if($order['jotform_error']): ?><p class="small text-danger mt-3"><?= esc($order['jotform_error']) ?></p><?php endif; ?><?php if($order['jotform_status']!=='synced'): ?><button class="btn btn-outline-brand w-100 mt-3" type="button" id="retry-sync"><i class="fa-solid fa-arrows-rotate me-2"></i>Retry Sync</button><?php endif; ?></section>
    </aside>
</div>
<script>document.getElementById('retry-sync')?.addEventListener('click',async function(){this.disabled=true;const original=this.innerHTML;this.innerHTML='<i class="fa-solid fa-spinner fa-spin me-2"></i>Syncing';const box=document.getElementById('sync-message');try{const response=await fetch('/api/jotform/orders/<?= esc($orderId) ?>',{method:'POST',headers:{'Accept':'application/json'}});const result=await response.json();if(!response.ok)throw new Error(result.message||'Sync failed');location.reload();}catch(error){box.innerHTML='<div class="alert alert-danger"></div>';box.firstElementChild.textContent=error.message;this.disabled=false;this.innerHTML=original;}});</script>
<?= view('components/admin_page_end') ?>
